    return !!state
      && state.chargesRemaining > 0
      && ctx.primary > 0
      && ctx.query.alive(ctx.primary)
      && ctx.query.inventoryItems(ctx.actor).includes(ctx.primary);
  },
  otherwise(ctx) {
    const state = stateOf(ctx);
