    : ((ctx.query.worldStep() | 0) + Math.max(1, state.cooldownTurns | 0));

  ctx.mutate.patchComponent(ctx.target, FountainState, {
    chargesRemaining,
    dryUntilStep,
  });
  ctx.mutate.record(FountainOutcomeApplied, {
    actor: ctx.actor,
    fountain: ctx.target,
    item,
    verb: ctx.verb,
    outcome: outcomeId,
    ruleId: String(ctx.params.ruleId || ""),
