    ctx.io.emit(new FountainDried({
      actor: ctx.actor,
      targetId: ctx.target,
      cooldownTurns: state.cooldownTurns,
      dryUntilStep,
    }));
  }
  return RuleResult.handled({ outcomeId });
}

