    if (state && state.chargesRemaining <= 0) {
      ctx.io.emit(new FountainDried({
        actor: ctx.actor,
        targetId: ctx.target,
        cooldownTurns: state.cooldownTurns,
        dryUntilStep: state.dryUntilStep,
      }));
    }
